1: import type { Node } from "./_shared";
2: import type { Expr } from "./index";
3: 
4: export interface Call extends Node<"Call"> {
5:   readonly callee: Expr;
6:   readonly args: readonly Expr[];
7: }
8: 
9: export interface Index extends Node<"Index"> {
10:   readonly target: Expr;
11:   readonly index: Expr;
12: }
13: 
14: /**
15:  * Property access `receiver.name`. Always evaluates to a Value — the kind
16:  * depends on what the method registry has under `name` for the receiver's
17:  * value kind: a getter fires and pushes its result; a method allocates a
18:  * `bound_native`; an unknown name throws `NoSuchProperty` at runtime.
19:  *
20:  * Method-call form `arr.push(x)` is NOT a distinct AST node — it parses as
21:  * a `Call` whose `callee` is a `PropertyAccess`.
22:  */
23: export interface PropertyAccess extends Node<"PropertyAccess"> {
24:   readonly receiver: Expr;
25:   readonly name: string;
26: }
